  "identity": {
    "name": "Lava Mouth",
    "tagline": "Small batch. Big mouth. Real fire.",
    "one_line_description": "Lava Mouth is a small-batch hot sauce brand making bold, playfully irreverent sauces for heat lovers who eat with personality.",
    "domain": "food_beverage_cpg",
    "subdomain": "small-batch hot sauce brand",
    "voice": [
